const CACHE='camera-trainer-v3';const ASSETS=['./','./index.html','./photo.html','./photo.js','./photo-data.js','./photo.css','./photos/attribution.json','./photos/photo-0.jpg','./photos/photo-2.jpg','./photos/photo-4.jpg','./photos/photo-7.jpg','./photos/photo-10.jpg','./photos/photo-11.jpg','./style.css','./app.js','./motion.js','./learning.js','./lessons.js','./missions.js','./vendor/three.module.js','./vendor/three.core.js','./manifest.webmanifest','./icon.svg','./icon-180.png','./icon-192.png','./icon-512.png'];
self.addEventListener('install',e=>e.waitUntil(caches.open(CACHE).then(c=>c.addAll(ASSETS)).then(()=>self.skipWaiting())));
self.addEventListener('activate',e=>e.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k!==CACHE&&k.startsWith('camera-trainer-')).map(k=>caches.delete(k)))).then(()=>self.clients.claim())));
self.addEventListener('fetch',e=>{if(e.request.method==='GET'&&new URL(e.request.url).origin===self.location.origin)e.respondWith(fetch(e.request).then(r=>{if(r.ok){const copy=r.clone();caches.open(CACHE).then(c=>c.put(e.request,copy));}return r;}).catch(()=>caches.match(e.request)));});
